def table(headers, rows):
    return '<table><thead><tr>'+''.join('<th scope="col">'+e(str(x))+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">' if i == 0 else '<td>')+e(str(x))+('</th>' if i == 0 else '</td>') for i,x in enumerate(row))+'</tr>' for row in rows)+'</tbody></table>'

def details(headers, rows, note=''):
    return '<details class="data-details"><summary>Data &amp; how to read it</summary>'+table(headers,rows)+'<p>'+e(note)+'</p></details>'

def figure(label, title, body, caption, data=''):
    return '<figure class="story-figure"><p class="figure-label">'+label+'</p><p class="figure-title">'+title+'</p>'+body+'<figcaption>'+caption+'</figcaption>'+data+'</figure>'

def icons(n, cls='', element='i'):
    return ''.join(f'<{element} class="{cls}" style="--i:{i%40}"></{element}>' for i in range(n))

def bar(label, value, maxval=100, suffix='%', cls=''):
    return f'<div class="bar-row {cls}"><div class="row-label"><span>{label}</span><b>{value}{suffix}</b></div><div class="bar-track" aria-hidden="true"><div class="bar-fill" style="--v:{value/maxval*100}"></div></div></div>'

