def lease_graphic():
    marks=[]
    for i in range(100):
        ok=i<57;j=i if ok else i-57
        x=(35 if ok else 300)+(j%(6 if ok else 5))*21;y=22+(j//(6 if ok else 5))*20
        sx=145+(i%10)*21;sy=22+(i//10)*20
        marks.append(f'<circle class="lease-mark {"success" if ok else "unrecorded"}" cx="{x}" cy="{y}" r="7" data-sx="{sx}" data-sy="{sy}" data-x="{x}" data-y="{y}"/>')
    return '<svg class="lease-morph" viewBox="0 0 450 225" role="img" aria-label="100 searches: approximately 57 with a recorded lease within one year and 43 without that outcome.">'+''.join(marks)+'</svg>'
housing[3]=re.sub(r'<div class="search-dots".*?</div>',lambda _:lease_graphic(),housing[3],flags=re.S)

def audit_graphic():
    marks=[]
    for i in range(320):
        group=0 if i<57 else 1 if i<87 else 2
        j=i if group==0 else i-57 if group==1 else i-87
        x=12+(j%20)*22; y=[38,110,182][group]+(j//20)*9
        sx=12+(i%20)*22; sy=38+(i//20)*14
        marks.append(f'<rect class="audit-mark group-{group}" x="{x}" y="{y}" width="14" height="6" rx="1" data-sx="{sx}" data-sy="{sy}" data-x="{x}" data-y="{y}"/>')
    return '<svg class="audit-morph" viewBox="0 0 450 300" role="img" aria-label="320 offices: 57 offered the selected clinician, 30 an alternate, and 233 no appointment."><g class="audit-labels"><text x="12" y="24">57 · Selected clinician</text><text x="12" y="97">30 · Alternate clinician</text><text x="12" y="169">233 · No appointment obtained</text></g>'+''.join(marks)+'</svg>'
health[2]=figure('03 / Same 320 offices','From directory to appointment', '<div class="big-number">27.2<span>%</span></div><p class="metric-caption">87 offices offered an appointment</p>'+audit_graphic(), '2023 calls · four cities · 57 + 30 = 87 offers out of 320 offices. The marks retain their identity as they regroup; their starting positions do not encode city. An offer is not completed treatment.', details(['Outcome','Offices'],[('Selected clinician',57),('Alternate clinician',30),('No appointment obtained',233)],'Mutually exclusive outcomes, not successive dropouts. JAMA, 2024.'))
