def render(topic, route, figures, ids, labels, title, hero_title, dek, art, category, other):
    chapters=[]
    for idx,(scene,visual,sid) in enumerate(zip(COPY[topic],figures,ids)):
        sources=list(scene['sources'])
        if topic=='medicaid' and idx==1:
            sources=[{'label':'JAMA: audit methods and results','url':SOURCES['jama']}]
        sourcehtml=''.join(f'<a href="{e(s["url"],quote=True)}">{e(s["label"])} ↗</a>' for s in sources)
        paras=''.join(f'<div class="story-step" data-step="{j}"><p>{e(p)}</p></div>' for j,p in enumerate(scene['paragraphs']))
        chapters.append(f'<section class="story-chapter" id="{sid}" aria-labelledby="heading-{sid}"><div class="chapter-inner"><header class="chapter-heading"><p class="eyebrow">{idx+1:02} / {labels[idx]}</p><h2 id="heading-{sid}">{e(scene["title"].split(". ",1)[1])}</h2></header><div class="scene-grid"><div class="scene-copy">{paras}'+(f'<div class="scene-sources">{sourcehtml}</div>' if sources else '')+f'</div>{visual}</div></div></section>')
    navigation=''.join(f'<a href="#{sid}" aria-label="{i+1}. {label}">{i+1:02}<span class="nav-label"> {label}</span></a>' for i,(sid,label) in enumerate(zip(ids,labels)))
    reslinks=(['hud','furman','urban','trial'] if topic=='housing' else ['medicaid','jama','oig'])
    names={'hud':'HUD: voucher information and local assistance','furman':'Furman Center: success rates, methods and limitations','urban':'Urban Institute: landlord acceptance study','trial':'Creating Moves to Opportunity: trial and research materials','medicaid':'Medicaid.gov: managed care','jama':'JAMA: four-city appointment audit','oig':'HHS inspector general: networks and directory accuracy'}
    sources=''.join(f'<a href="{SOURCES[k]}">{names[k]} ↗</a>' for k in reslinks)
    html=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex, nofollow, noarchive"><meta name="googlebot" content="noindex, nofollow, noarchive"><title>{e(title)} | Available ≠ Accessible</title><meta name="description" content="{e(dek,quote=True)}"><meta property="og:title" content="{e(title,quote=True)}"><meta property="og:description" content="{e(dek,quote=True)}"><meta name="theme-color" content="#f8f6f0"><link rel="icon" href="/favicon.svg"><link rel="stylesheet" href="/collection.css?v=20260923-meet"><link rel="stylesheet" href="/access-stories.css?v=20260923"><script src="/collection.js?v=20260923-meet" defer></script><script src="/access-stories.js?v=1" defer></script><link rel="stylesheet" href="/story-refinements.css?v=20260923"><script src="/story-refinements.js?v=20260923" defer></script><link rel="stylesheet" href="/shared-footer.css?v=20260923"></head>
<body class="access-story {'health-story' if topic=='medicaid' else 'housing-story'}"><a class="skip" href="#main">Skip to story</a>{HEADER}<div class="story-progress" aria-hidden="true"><span></span></div><main id="main"><section class="story-hero"><div><p class="eyebrow">{category} / 4–6 min</p><h1>{hero_title}</h1><p class="dek">{e(dek)}</p><p class="byline">By <a href="/about/">Megan Quigley</a> · A synthesis of published research</p><a class="story-start" href="#{ids[0]}">Follow the story <span aria-hidden="true">↓</span></a></div><div class="hero-visual">{art}<p class="art-caption">{other['motif']}</p></div></section><div class="story-toolbar"><nav class="chapter-nav" aria-label="Story chapters">{navigation}</nav><button data-reading-toggle aria-pressed="false" hidden>Read without animation</button></div>{''.join(chapters)}
<section class="story-resources" id="sources"><p class="eyebrow">Keep looking</p><h2>The evidence behind the story.</h2><div class="resource-columns"><div><h3>Read the research</h3>{sources}<a href="/data/{topic}-access.json" download>Download chart data &amp; source notes ↓</a></div><div><h3>What this story can tell us</h3><p>{other['limit']}</p><p>Illustrations explain a process. They do not depict an interviewed person. Recommendations and editorial questions are labeled separately from measured results.</p><a href="/support/">Explore public-benefit support →</a></div></div><a class="story-next" href="{other['url']}"><span>Read another story</span>{other['title']} →</a></section></main><footer class="global-footer"><a href="/">Available ≠ Accessible</a><span>Independent research on public benefit access.</span></footer></body></html>'''
    path=DIST / 'case-studies' / route / 'index.html'
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(html)

render('housing','housing',housing,['approved','search','doors','lease','support','delivery'],['Benefit','Search','Barriers','Leases','Support','Delivery'], 'What does it take to find a home with a voucher?', 'What does it take<br>to find a home<br><em>with a voucher?</em>', 'Rental assistance is an important beginning. Follow the distance between approval and a signed lease.', HOUSE, 'Housing assistance', {'motif':'From approval to a front-door key','limit':'This story begins after a voucher is issued. The 2022 outcome is a one-year lease-up estimate at agencies passing data-quality checks. The landlord study and neighborhood trial have different populations and outcomes. None measures access among everyone eligible for housing assistance.','url':'/case-studies/health/','title':'What does it take to get mental-health care through Medicaid?'})
render('medicaid','health',health,['covered','listed','contacted','waiting','accountable'],['Coverage','Directory','Calls','Waits','Access'], 'What does it take to get mental-health care through Medicaid?', 'What does it take to get<br>mental-health care<br><em>through Medicaid?</em>', 'A provider directory makes care look findable. What happens when someone tries to use it?', HEALTH, 'Medicaid / mental-health care', {'motif':'From a coverage card to an appointment','limit':'This is an audit of adult psychiatric prescribing appointments in four cities, with calls in 2023. It is not a national rate, a study of every form of therapy, or a record of completed treatment. The study did not include a commercial-insurance comparison group.','url':'/case-studies/housing/','title':'What does it take to find a home with a voucher?'})

