# Update only the shared case-study menu on existing pages; preserve their bodies.
for path in DIST.rglob('*.html'):
    if path.parts[-3:-1] in [('case-studies','housing'),('case-studies','health')]:
        continue
    text=path.read_text()
    text=re.sub(r'(<details class="case-menu">.*?<div>).*?(</div></details>)',lambda m:m[1]+NAV+m[2],text,flags=re.S)
    footer = '<footer class="global-footer"><a href="/">Available ≠ Accessible</a><span>Independent research on public benefit access.</span></footer>'
    text=re.sub(r'<footer\b[^>]*>.*?</footer>',lambda _:footer,text,flags=re.S) if '<footer' in text else text.replace('</body>',footer+'</body>')
    if '/shared-footer.css' not in text:
        text=text.replace('</head>','<link rel="stylesheet" href="/shared-footer.css?v=20260923"></head>')
    path.write_text(text)

